package com.whaa.shop.recommendation.controller;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.whaa.shop.common.api.ApiResponse;import com.whaa.shop.common.exception.BusinessException;import com.whaa.shop.recommendation.domain.HomeBanner;import com.whaa.shop.recommendation.infrastructure.HomeBannerMapper;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.List;
@RestController public class HomeBannerController {private final HomeBannerMapper banners;public HomeBannerController(HomeBannerMapper b){banners=b;}@GetMapping("/api/v1/shop/home-banners")ApiResponse<List<HomeBanner>> shop(){return ApiResponse.ok(banners.selectList(new LambdaQueryWrapper<HomeBanner>().eq(HomeBanner::getEnabled,true).orderByAsc(HomeBanner::getSortOrder)));}@GetMapping("/api/v1/admin/home-banners")ApiResponse<List<HomeBanner>> admin(){return ApiResponse.ok(banners.selectList(new LambdaQueryWrapper<HomeBanner>().orderByAsc(HomeBanner::getSortOrder)));}
 @PostMapping("/api/v1/admin/home-banners")ApiResponse<HomeBanner> create(@RequestBody HomeBanner b){b.setId(null);return ApiResponse.ok(save(b));}@PutMapping("/api/v1/admin/home-banners/{id}")ApiResponse<HomeBanner> update(@PathVariable Long id,@RequestBody HomeBanner b){b.setId(id);return ApiResponse.ok(save(b));}@DeleteMapping("/api/v1/admin/home-banners/{id}")ApiResponse<Void> delete(@PathVariable Long id){banners.deleteById(id);return ApiResponse.ok();}private HomeBanner save(HomeBanner b){if(b.getTitle()==null||b.getTitle().isBlank()||b.getImageUrl()==null||b.getImageUrl().isBlank())throw new BusinessException("轮播标题和图片不能为空");if(b.getButtonText()==null||b.getButtonText().isBlank())b.setButtonText("立即选购");if(b.getSortOrder()==null)b.setSortOrder(0);if(b.getEnabled()==null)b.setEnabled(true);LocalDateTime now=LocalDateTime.now();b.setUpdatedAt(now);if(b.getId()==null){b.setCreatedAt(now);banners.insert(b);}else banners.updateById(b);return b;}}
